#pragma once

#include <string_view>

inline constexpr std::string_view kPortalPage = R"HTML(<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mouse Bridge</title><style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#111;color:#eee}body{margin:0;padding:20px;max-width:680px;margin:auto}h1{font-size:1.35rem;margin:0 0 4px}h2{font-size:1rem;margin:24px 0 10px;color:#bbb}.sub,#status{color:#999;font-size:.9rem}.card{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid #292929}.info{min-width:0;flex:1}.name{font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.meta{font:12px ui-monospace,monospace;color:#888;margin-top:3px}.presence{display:flex;align-items:center;gap:7px;margin-top:5px;font:12px system-ui,sans-serif;font-weight:650}.status-dot{width:8px;height:8px;border-radius:50%;display:inline-block}.presence.connected{color:#55cf80}.presence.connected .status-dot{background:#3ecf70;box-shadow:0 0 0 2px #173e25}.presence.ready{color:#78a7ff}.presence.ready .status-dot{background:#4f8cff;box-shadow:0 0 0 2px #1b3159}.presence.offline{color:#777}.presence.offline .status-dot{background:#666;box-shadow:0 0 0 2px #292929}button{border:0;border-radius:8px;padding:9px 12px;background:#2b66e3;color:white;font-weight:650}button.alt{background:#303030}button.danger{background:#6e3030}button.danger.confirm{background:#a23b3b}button:disabled{opacity:.45}.actions{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}.empty{padding:14px 0;color:#777}.saved{color:#78a7ff}#close{float:right;margin-top:-34px}@media(max-width:500px){body{padding:16px}.card{align-items:flex-start;flex-direction:column}.actions{width:100%}.actions button{flex:1}}
</style></head><body><h1>Mouse Bridge</h1><div class="sub">Select a BLE mouse for ESP32-S3</div><button id="close" class="alt">Close setup</button><div id="status">Loading…</div><h2>Previously connected</h2><div id="saved"></div><h2>Nearby devices</h2><div id="nearby"></div>
<script>
const $=id=>document.getElementById(id);let busy=false,pendingDelete='';
const labels={idle:'Ready',scanning:'Searching for the selected device…',portal:'Scanning for BLE devices…',switching:'Switching devices…',connecting:'Connecting…',connected:'Connected',success:'Connected. Setup Wi-Fi will close shortly.',failed:'Connection failed'};
function button(text,cls,fn,disabled=false){const b=document.createElement('button');b.textContent=text;b.className=cls||'';b.disabled=disabled;b.onclick=fn;return b}
function form(d){return 'address='+encodeURIComponent(d.address)+'&type='+d.type}
async function post(path,body=''){busy=true;try{const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});if(!r.ok)throw new Error(await r.text());pendingDelete='';await load()}catch(e){$('status').textContent='Action failed: '+e.message}finally{busy=false}}
function info(d){const box=document.createElement('div');box.className='info';const n=document.createElement('div');n.className='name';n.textContent=d.name;const m=document.createElement('div');m.className='meta';m.textContent=d.address+(d.rssi===undefined||d.rssi===null?'':' · '+d.rssi+' dBm');box.append(n,m);return box}
function renderSaved(items){const root=$('saved');root.replaceChildren();if(!items.length){root.innerHTML='<div class="empty">No saved devices</div>';return}items.forEach(d=>{const row=document.createElement('div');row.className='card';const box=info(d);const state=d.connected?'connected':d.inRange?'ready':'offline';const p=document.createElement('div');p.className='presence '+state;const dot=document.createElement('span');dot.className='status-dot';p.append(dot,document.createTextNode(state==='connected'?'Connected':state==='ready'?'Ready':'Offline'));box.append(p);row.append(box);const a=document.createElement('div');a.className='actions';if(d.connected)a.append(button('Disconnect','alt',()=>post('/api/disconnect'),busy));else a.append(button('Connect','',()=>post('/api/connect',form(d)),busy||!d.inRange));const key=d.address+'/'+d.type;const armed=pendingDelete===key;a.append(button(armed?'Click again to delete':'Delete','danger'+(armed?' confirm':''),()=>{if(armed)post('/api/forget',form(d));else{pendingDelete=key;renderSaved(items)}},busy));row.append(a);root.append(row)})}
function renderNearby(items){const root=$('nearby');root.replaceChildren();if(!items.length){root.innerHTML='<div class="empty">Scanning for nearby devices…</div>';return}items.forEach(d=>{const row=document.createElement('div');row.className='card';const box=info(d);if(d.saved){const mark=document.createElement('div');mark.className='meta saved';mark.textContent='Saved';box.append(mark)}row.append(box);const a=document.createElement('div');a.className='actions';a.append(button(d.busy?'Connecting…':'Connect','',()=>post('/api/connect',form(d)),busy||d.busy));row.append(a);root.append(row)})}
async function load(){try{const r=await fetch('/api/state',{cache:'no-store'});const s=await r.json();$('status').textContent=labels[s.phase]||s.phase;renderSaved(s.saved);renderNearby(s.nearby)}catch(e){$('status').textContent='Lost connection to the setup portal'}setTimeout(load,1000)}
$('close').onclick=()=>post('/api/close');load();
</script></body></html>)HTML";
